import os,sys
from playwright.sync_api import sync_playwright
URL='file://'+os.path.abspath('sellora.html');R=[]
def ok(n,c,d=''):R.append((n,bool(c)));print(('PASS ' if c else 'FAIL ')+n+(' :: '+str(d) if d else ''),flush=True)
with sync_playwright() as p:
    b=p.chromium.launch();ctx=b.new_context(viewport={'width':1280,'height':800});pg=ctx.new_page();errs=[]
    pg.on('pageerror',lambda e:errs.append(str(e)[:200]))
    pg.goto(URL);pg.wait_for_timeout(900)
    E=pg.evaluate;go=lambda r:(E("location.hash='%s'"%r),pg.wait_for_timeout(350))
    # data: products into a manual collection + tag rule automated collection
    E("S.products.forEach((p,i)=>{p.status='Active';p.tags=i%2?['gloves']:['suit'];p.cols=[]});save()")
    # --- collections
    go('products-collections')
    pg.click('text=Create collection');pg.wait_for_timeout(400);pg.fill('#x7c1','Track Day');pg.check('input[name=x7ct][value=Manual]')
    pg.check('[data-x7pp="%d"]'%E("S.products[0].id"));E("document.querySelector('#m9colsave').click()");pg.wait_for_timeout(300);pg.goto(pg.url.split('#')[0]+'#products-collections');pg.wait_for_timeout(300)
    c=E("({t:S.collections.find(c=>c.title==='Track Day')?.type,n:x7colCount('Track Day'),cols:S.cols.includes('Track Day')})")
    ok('collection manual type kept',c['t']=='Manual',c);ok('manual count = 1',c['n']==1,c);ok('listed in product Add collections',c['cols'])
    pg.click('text=Create collection');pg.wait_for_timeout(400);pg.fill('#x7c1','Gloves');pg.check('input[name=x7ct][value=Automated]');pg.select_option('[data-rf]','tag');pg.select_option('[data-ro]','eq');pg.fill('[data-rv]','gloves');E("document.querySelector('#m9colsave').click()");pg.wait_for_timeout(300);pg.goto(pg.url.split('#')[0]+'#products-collections');pg.wait_for_timeout(300)
    exp=E("S.products.filter(p=>p.tags.includes('gloves')).length");n=E("x7colCount('Gloves')")
    ok('automated rule count',n==exp and E("S.collections.find(c=>c.title==='Gloves').type")=='Automated',(n,exp))
    shown=E("[...document.querySelectorAll('[data-x7n]')].map(e=>e.dataset.x7n+'='+parseInt(e.textContent))")
    ok('list counts not hardcoded',('Track Day=1' in shown) and ('Gloves=%d'%exp in shown),shown)
    ok('no mojibake icon','ðŸ' not in pg.content())
    E("SF.open('collection:Gloves')");pg.wait_for_timeout(400)
    names=E("[...document.querySelectorAll('#xsf [data-sf^=\"product:\"]')].map(e=>e.textContent).join('|')")
    ids=E("[...new Set([...document.querySelectorAll('#xsf [data-sf^=\"product:\"]')].map(e=>+e.dataset.sf.split(':')[1]))]")
    ok('collection page filters',len(ids)==exp and all(E("S.products.find(p=>p.id===%d).tags.includes('gloves')"%i) for i in ids),ids)
    E("document.querySelector('#xsfclose')?.click()");go('home')
    # --- hero image + featured collection on storefront
    E("""(function(){var t=live();var h=t.pg.home.find(s=>/hero/.test(s.type));h.s.img='data:image/gif;base64,R0lGODlhAQABAIAAAP///wAAACwAAAAAAQABAAACAkQBADs=';var f=t.pg.home.find(s=>s.type==='featured');if(f)f.s.col='Track Day';save()})()""")
    E("SF.open('home')");pg.wait_for_timeout(500)
    ok('storefront hero shows image',E("!!document.querySelector('#xsf [data-sid] [style*=\"data:image/gif\"],#xsf [style*=\"data:image/gif\"]')"))
    fc=E("(function(){var t=live(),f=t.pg.home.find(s=>s.type==='featured');var el=f&&document.querySelector('#xsf [data-sid=\"'+f.id+'\"]');return el?[...el.querySelectorAll('.pc')].length:-1})()")
    ok('featured collection shows only its products',fc==1,fc)
    E("document.querySelector('#xsfclose')?.click()")
    # --- theme typing integrity (real keys)
    go('themes');E("edit(S.live)");pg.wait_for_timeout(400)
    sid=E("live().pg.home.find(s=>/hero/.test(s.type)).id");pg.click('[data-ed="tog:%s"]'%sid);pg.wait_for_timeout(200)
    for k,txt in [('h','Fast Lane Racing Gear'),('sub','Race ready. Every day.')]:
        sel='#edl [data-sid="%s"][data-sk="%s"]'%(sid,k);pg.click(sel);pg.keyboard.press('Control+A');pg.keyboard.type(txt,delay=25);pg.wait_for_timeout(200)
        pg.keyboard.press('Home');pg.keyboard.type('X',delay=10);pg.wait_for_timeout(200)
        got=pg.eval_on_selector(sel,'e=>e.value');ok('typing intact '+k,got=='X'+txt and E("document.activeElement.dataset.sk")==k,got)
    pg.wait_for_timeout(200);ok('marquee edit reaches preview','Race ready. Every day.' in E("document.querySelector('#ep').textContent"))
    pg.click('[data-ed="theme"]');pg.wait_for_timeout(200)
    ok('palette slots present',E("document.querySelectorAll('#edl [data-x7pal]').length")>=9)
    ok('default theme is Daybreak with Sellora green',E("live().name")=='Daybreak' and E("live().ac").lower()=='#2e6b4f')
    ok('color hex inputs',E("document.querySelectorAll('#edl .x7hex').length")>=12)
    E("document.querySelector('#os').click()")
    # --- pages CRUD
    go('pages');ok('seeded about/contact',E("['about','contact'].every(h=>S.pages.some(p=>p.h===h))"))
    pg.click('text=Add page');pg.fill('#x7p1','Size Guide');pg.click('#x7p2');pg.keyboard.type('Measure your chest.');pg.check('#x7p7');pg.click('#xok');pg.wait_for_timeout(300)
    ok('page created',E("!!S.pages.find(p=>p.h==='size-guide')"))
    E("SF.open('page:size-guide')");pg.wait_for_timeout(300);ok('storefront renders page','Measure your chest.' in E("document.querySelector('#xsf').textContent"))
    ok('menu links to page',E("!!document.querySelector('#xsf header [data-sf=\"page:size-guide\"]')"));E("document.querySelector('#xsfclose')?.click()");go('pages')
    i=E("S.pages.findIndex(p=>p.h==='size-guide')");pg.click('[data-x="x7pg:%d"] >> nth=0'%i if False else 'button[data-x="x7pg:%d"]'%i);pg.fill('#x7p1','Sizing');pg.click('#xok');pg.wait_for_timeout(300)
    ok('page edited',E("S.pages[%d].t"%i)=='Sizing')
    pg.once('dialog',lambda d:d.accept());pg.click('button[data-x="x7pgdel:%d"]'%i);pg.wait_for_timeout(300);ok('page deleted',not E("S.pages.some(p=>p.h==='size-guide')"))
    # --- store address persistence + pickup
    go('s-general');pg.fill('#xaddr','12 Gulberg III, Lahore');pg.wait_for_timeout(100);pg.reload();pg.wait_for_timeout(900)
    ok('address persists',E("S.addr")=='12 Gulberg III, Lahore');ok('pickup follows address',E("S.pickup.locs[0].addr")=='12 Gulberg III, Lahore')
    # --- markets
    go('markets');ok('market badge full name','Pakistani Rupee (PKR)' in E("document.querySelector('#main').textContent"))
    pg.click('text=Add market');ok('PKR in dialog',E("[...document.querySelectorAll('#x7m2 option')].some(o=>o.value==='PKR')") and E("document.querySelectorAll('#x7m2 option').length")>50)
    pg.fill('#x7m1','Pak 2');pg.select_option('#x7m2','PKR');pg.fill('#x7m3','Pakistan');pg.click('#xok');pg.wait_for_timeout(200)
    ok('duplicate currency warns',E("!!document.querySelector('#x7merge')"));pg.click('#xok');pg.wait_for_timeout(300)
    ok('merged',not E("S.marketsList.some(m=>m.name==='Pak 2')"))
    go('shipping-zones');ok('zone shown in PKR','Pakistani Rupee (PKR)' in E("document.querySelector('#main').textContent") and 'PKR' in E("document.querySelector('#main').innerHTML"))
    pg.click('#main [data-x^="zedit:"] >> nth=0');pg.wait_for_timeout(200);ok('rate table editor',E("document.querySelectorAll('#x7rt .x7rr').length")>0 and not E("!!document.querySelector('#xz3')"))
    E("closeM()")
    # --- product: variants follow base price, save+add another
    go('productform');pg.wait_for_timeout(300)
    ok('save and add another button',E("!!document.querySelector('#x7saveadd')"))
    # --- sign out / sign up
    E("document.querySelector('#so').click()");pg.wait_for_timeout(400)
    ok('sign out shows login',E("getComputedStyle(document.querySelector('#auth')).display")!='none' and 'Log in' in E("document.querySelector('#auth').textContent"))
    pg.reload();pg.wait_for_timeout(900);ok('stays signed out after reload',E("getComputedStyle(document.querySelector('#auth')).display")!='none')
    pg.click('#asw');pg.wait_for_timeout(300);pg.click('[data-m13p=grow]');pg.wait_for_timeout(300);pg.fill('#a1','Second Shop');pg.fill('#a2','two@example.com');pg.fill('#a3','password123');pg.click('#ab');pg.wait_for_timeout(900)
    ok('new store created',E("S.name")=='Second Shop' and E("U")=='two@example.com',E("S.name"))
    E("document.querySelector('#so').click()");pg.wait_for_timeout(300)
    first=E("Object.keys(DB.d).find(k=>k!=='two@example.com')");pg.click('[data-x7st="%s"]'%first);pg.fill('#a3','password123');pg.click('#ab');pg.wait_for_timeout(900)
    ok('log back into first store',E("U")==first and E("S.addr")=='12 Gulberg III, Lahore',E("S.name"))
    ok('no page errors',not errs,errs)
    b.close()
f=[n for n,c in R if not c];print('%d/%d passed'%(len(R)-len(f),len(R)));sys.exit(1 if f else 0)
